SELECT percentile_rank, COUNT(*) OVER (PARTITION BY percentile_rank) AS num_patients, MAX(los) OVER (PARTITION BY percentile_rank ORDER BY los DESC) AS longest_stay, SUM(CASE WHEN interpretation = 'Mortality' THEN 1 ELSE 0 END) OVER (PARTITION BY percentile_rank) AS num_deaths FROM (SELECT subject_id, hadm_id, stay_id, first_careunit, last_careunit, intime, outtime, los, gender, anchor_age, anchor_year, anchor_year_group, icd_code, test_name, interpretation, (CASE WHEN (outtime - intime) > 24 THEN (outtime - intime) ELSE 24 END) AS instability_score FROM icustays JOIN patients ON icustays.subject_id = patients.subject_id JOIN diagnoses_icd ON icustays.hadm_id = diagnoses_icd.subject_id JOIN microbiologyevents ON icustays.hadm_id = microbiologyevents.subject_id WHERE patients.gender = 'F' AND patients.anchor_age BETWEEN 55 AND 65 AND microbiologyevents.test_name = 'pneumonia' AND microbiologyevents.interpretation = 'Susceptible') subquery) s WHERE percentile_rank <= 0.6;